<?php
require_once __DIR__ . '/../config/security.php';
start_secure_session();
require_once __DIR__ . '/../config/database.php';
require_portal_role($conn, 'assistant', false);
require_once __DIR__ . '/../includes/appointment_helpers.php';

$uid=(int)$_SESSION['user_id'];$msg='';$type='';
function staff_unavailable(mysqli $conn,int $userId,string $date,string $time): bool { return sd_staff_unavailable($conn,$userId,$date,$time); }
$dentists=[];$r=$conn->query("SELECT id,first_name,last_name FROM users WHERE role='dentist' AND status='active' ORDER BY last_name,first_name");if($r){while($d=$r->fetch_assoc())$dentists[]=$d;}
$staff=[['id'=>$uid,'first_name'=>$_SESSION['first_name']??'Assistant','last_name'=>$_SESSION['last_name']??'','role'=>'assistant']];foreach($dentists as $d)$staff[]=$d+['role'=>'dentist'];
$patients=[];$r=$conn->query("SELECT id,first_name,last_name,email FROM users WHERE role='patient' AND status='active' ORDER BY last_name,first_name");if($r){while($p=$r->fetch_assoc())$patients[]=$p;}
$services=[];$r=$conn->query("SELECT name FROM services WHERE is_active=1 ORDER BY id");if($r){while($s=$r->fetch_assoc())$services[]=$s['name'];}if(!$services)$services=['Dental Checkup','Dental Cleaning','Dental Restoration','Tooth Extraction','Consultation'];

if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!csrf_valid($_POST['csrf_token']??null)){ $msg='Your session expired. Refresh and try again.'; $type='error'; }
  else {
  $action=$_POST['action']??'';
  if($action==='block_provider'){
    $provider=(int)($_POST['provider_id']??0);$date=$_POST['unavailable_date']??'';$allDay=isset($_POST['all_day'])?1:0;$start=$allDay?null:($_POST['start_time']??null);$end=$allDay?null:($_POST['end_time']??null);$reason=trim($_POST['reason']??'Unavailable');
    $ck=$conn->prepare("SELECT id FROM users WHERE id=? AND role IN ('assistant','dentist') AND status='active'");$ck->bind_param('i',$provider);$ck->execute();$valid=$ck->get_result()->num_rows>0;$ck->close();
    if(!$valid||!clinic_open_day($date)||(!$allDay&&(!$start||!$end||$start>=$end))){$msg='Choose a valid staff member and a Monday–Saturday schedule.';$type='error';}
    else{$st=$conn->prepare("INSERT INTO provider_unavailability(user_id,unavailable_date,start_time,end_time,all_day,reason,created_by) VALUES(?,?,?,?,?,?,?)");$st->bind_param('isssisi',$provider,$date,$start,$end,$allDay,$reason,$uid);$st->execute();$st->close();$msg='Unavailable schedule saved.';$type='success';}
  } elseif($action==='walkin'){
    $pid=(int)($_POST['patient_id']??0);$dentistId=(int)($_POST['dentist_id']??0);$date=$_POST['appointment_date']??date('Y-m-d');$time=substr($_POST['appointment_time']??date('H:i'),0,5);$service=trim($_POST['appointment_type']??'');$reason=trim($_POST['reason']??'Walk-in patient');
    if(!$pid||!$dentistId||!in_array($service,$services,true)){$msg='Select a registered patient, dentist, and service.';$type='error';}
    elseif(!clinic_open_day($date)){$msg='The clinic accepts appointments Monday to Saturday only. Sundays are closed.';$type='error';}
    else{$check=$conn->prepare("SELECT id FROM appointments WHERE dentist_id=? AND appointment_date=? AND appointment_time=? AND status IN ('pending','approved') LIMIT 1");$check->bind_param('iss',$dentistId,$date,$time);$check->execute();$busy=$check->get_result()->num_rows>0;$check->close();if($busy){$msg='That dentist already has an appointment at this schedule.';$type='error';}elseif(staff_unavailable($conn,$dentistId,$date,$time)){$msg='That dentist marked this schedule as unavailable.';$type='error';}else{$st=$conn->prepare("INSERT INTO appointments(patient_id,dentist_id,appointment_date,appointment_time,appointment_type,reason,status) VALUES(?,?,?,?,?,?,'approved')");$st->bind_param('iissss',$pid,$dentistId,$date,$time,$service,$reason);$st->execute();$newId=$st->insert_id;$st->close();$title='Walk-in Appointment Recorded';$text='Your clinic visit on '.date('M d, Y',strtotime($date)).' at '.date('h:i A',strtotime($time)).' has been recorded.';$nt='appointment';$n=$conn->prepare('INSERT INTO notifications(patient_id,title,message,type,is_read) VALUES(?,?,?,?,0)');$n->bind_param('isss',$pid,$title,$text,$nt);$n->execute();$n->close();$pn=$conn->prepare('SELECT CONCAT(first_name,\' \',last_name) n FROM users WHERE id=?');$pn->bind_param('i',$pid);$pn->execute();$pname=(string)($pn->get_result()->fetch_assoc()['n']??'Patient');$pn->close();sd_notify_staff($conn,[],[$dentistId],'Walk-in appointment · '.$pname,$pname.' was recorded as a walk-in for '.$service.' on '.date('M d, Y',strtotime($date)).' at '.date('h:i A',strtotime($time)).'.',$newId,$pid,$uid);log_activity($conn,$uid,'Created walk-in appointment','Appointments','Appointment #'.$newId);$msg='Walk-in appointment recorded and assigned to the selected dentist.';$type='success';}}
  } elseif($action==='assign'){
    // Bookings made when no dentist was free (or a dentist who became unavailable) can be (re)assigned here.
    [$ok,$text]=sd_assign_dentist($conn,(int)($_POST['appointment_id']??0),(int)($_POST['dentist_id']??0),$uid);
    $msg=$ok?$text.' The dentist and the patient were notified.':$text;$type=$ok?'success':'error';
  } elseif($action==='cancel'){
    // Bookings are approved automatically; the assistant can still cancel an active appointment.
    [$ok,$text]=sd_cancel_appointment($conn,(int)($_POST['appointment_id']??0),$uid,'assistant',(string)($_POST['cancel_reason']??''));
    $msg=$ok?$text.' The patient was notified.':$text;$type=$ok?'success':'error';
  } else { $msg='Invalid action.'; $type='error'; }
  }
}
$rows=[];$r=$conn->query("SELECT a.*,u.first_name,u.last_name,d.first_name dentist_first,d.last_name dentist_last FROM appointments a JOIN users u ON u.id=a.patient_id LEFT JOIN users d ON d.id=a.dentist_id AND d.role='dentist' ORDER BY FIELD(a.status,'pending','approved','completed','rejected','cancelled'),a.appointment_date ASC,a.appointment_time ASC");if($r){while($x=$r->fetch_assoc())$rows[]=$x;}
$viewData=[];foreach($rows as $x)$viewData[(int)$x['id']]=sd_appointment_view_data($x);
$calendarRole='assistant';$calendarEvents=array_values(array_map(static fn($a)=>array_intersect_key($a,array_flip(['id','patient_id','dentist_id','appointment_date','appointment_time','appointment_type','reason','marked_teeth','status','first_name','last_name','email','dentist_first','dentist_last'])),array_filter($rows,static fn($a)=>in_array($a['status'],['pending','approved','completed'],true))));
$calendarBlocks=[];
$blockResult=$conn->query("SELECT p.id,p.unavailable_date,p.start_time,p.end_time,p.all_day,p.reason,CONCAT(u.first_name,' ',u.last_name) staff_name FROM provider_unavailability p JOIN users u ON u.id=p.user_id AND u.role='dentist' WHERE p.unavailable_date>=DATE_SUB(CURDATE(),INTERVAL 60 DAY) ORDER BY p.unavailable_date,p.start_time");
if($blockResult)while($b=$blockResult->fetch_assoc())$calendarBlocks[]=$b;

$view=($_GET['view']??'')==='calendar'?'calendar':'requests';
require '../includes/ui.php';ui_header($view==='calendar'?'Appointment View':'Appointment Requests','assistant');ui_sidebar('assistant','appointments.php');?>
<?php if($view==='calendar'):?>
<div class="page-head compact-head"><div><div class="eyebrow">APPOINTMENT DESK</div><h1>Appointment View</h1><div class="muted">Every patient appointment on one calendar. Click a date to see who is scheduled.</div></div><a class="btn btn-primary" href="appointments.php"><i class="fa-solid fa-list-check"></i> Appointment Requests</a></div><?php if($msg)flash($type,$msg);?>
<?php require '../includes/appointment_calendar.php'; ?>
<?php require '../includes/appointment_view_modal.php'; ?>
<?php else:?>
<div class="page-head compact-head"><div><div class="eyebrow">APPOINTMENT DESK</div><h1>Appointment Requests</h1><div class="muted">Online bookings are confirmed automatically. Review them here and record registered walk-in patients.</div></div><a class="btn btn-primary" href="appointments.php?view=calendar"><i class="fa-solid fa-calendar-days"></i> Appointment View</a></div><?php if($msg)flash($type,$msg);?>
<section class="card requests-card" data-live-region="requests"><div class="card-heading"><div><h2>Patient Appointments</h2><p class="muted">Patient bookings are approved automatically. Click View to see the date, time, service, concern and the teeth the patient marked.</p></div><span class="badge"><?=count($rows)?> total</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Patient</th><th>Schedule</th><th>Service / Reason</th><th>Status</th><th>Dentist</th><th>Action</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="empty">No appointments yet.</td></tr><?php endif;?><?php foreach($rows as $a):?><tr id="appointment-request-<?=$a['id']?>"><td><b><?=e($a['first_name'].' '.$a['last_name'])?></b><br><span class="muted">Patient #<?=$a['patient_id']?></span></td><td><?=e(date('M d, Y',strtotime($a['appointment_date'])))?><br><?=e(date('h:i A',strtotime($a['appointment_time'])))?></td><td><b><?=e($a['appointment_type'])?></b><br><span class="muted"><?=e($a['reason']?:'No reason provided')?></span></td><td><span class="status-pill <?=e($a['status'])?>"><?=e($a['status']==='rejected'?'Declined':ucfirst($a['status']))?></span></td><td><?=$a['dentist_first']?e($a['dentist_first'].' '.$a['dentist_last']):'<span class="badge status-inactive">Not assigned</span>'?><?php if(in_array($a['status'],['pending','approved'],true)&&strtotime($a['appointment_date'].' '.$a['appointment_time'])>=time()):?><form method="post" class="assign-dentist-form" style="display:flex;gap:6px;margin-top:6px"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="assign"><input type="hidden" name="appointment_id" value="<?=(int)$a['id']?>"><select name="dentist_id" required aria-label="Assign dentist"><option value=""><?=$a['dentist_first']?'Reassign…':'Assign…'?></option><?php foreach($dentists as $d):if((int)$d['id']===(int)$a['dentist_id'])continue;?><option value="<?=$d['id']?>"><?=e('Dr. '.$d['last_name'])?></option><?php endforeach;?></select><button class="btn btn-secondary btn-sm">Save</button></form><?php endif;?></td><td><button type="button" class="btn btn-primary btn-sm" data-view-appt="<?=(int)$a['id']?>">View</button></td></tr><?php endforeach;?></tbody></table></div></section>
<details class="card tool-panel"><summary><span><b>Register Walk-in Appointment</b><small>For an existing registered patient arriving at the clinic.</small></span><i class="fa-solid fa-chevron-down"></i></summary><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="walkin"><div class="field"><label>Patient *</label><select name="patient_id" required><option value="">Select registered patient</option><?php foreach($patients as $p):?><option value="<?=$p['id']?>"><?=e($p['last_name'].', '.$p['first_name'].' — '.$p['email'])?></option><?php endforeach;?></select></div><div class="field"><label>Dentist *</label><select name="dentist_id" required><option value="">Select dentist</option><?php foreach($dentists as $d):?><option value="<?=$d['id']?>"><?=e($d['last_name'].', '.$d['first_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Date *</label><input type="date" name="appointment_date" value="<?=date('Y-m-d')?>" required></div><div class="field"><label>Time *</label><input type="time" name="appointment_time" value="<?=date('H:i')?>" required></div><div class="field"><label>Service *</label><select name="appointment_type" required><option value="">Select service</option><?php foreach($services as $s):?><option><?=e($s)?></option><?php endforeach;?></select></div><div class="field"><label>Reason / Notes</label><input name="reason" value="Walk-in patient"></div><div class="actions full"><button class="btn btn-primary"><i class="fa-solid fa-person-walking"></i> Record Walk-in</button></div></form></details>
<details class="card tool-panel"><summary><span><b>Staff Availability</b><small>Mark a dentist or your assistant schedule as unavailable.</small></span><i class="fa-solid fa-chevron-down"></i></summary><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="block_provider"><div class="field"><label>Staff member</label><select name="provider_id" required><?php foreach($staff as $member):?><option value="<?=$member['id']?>"><?=e(($member['last_name']??'').', '.($member['first_name']??'').' — '.ucfirst($member['role']))?></option><?php endforeach;?></select></div><div class="field"><label>Date</label><input type="date" name="unavailable_date" min="<?=date('Y-m-d')?>" required></div><div class="field"><label><input type="checkbox" name="all_day" value="1" checked> All day</label></div><div class="field"><label>Start</label><input type="time" name="start_time" value="09:00"></div><div class="field"><label>End</label><input type="time" name="end_time" value="17:00"></div><div class="field"><label>Reason</label><input name="reason" placeholder="Leave, training, clinic duty"></div><div class="actions full"><button class="btn btn-primary">Save Unavailable Time</button></div></form></details>
<?php endif;?>
